import re

_UNITS = {
    1: ["s", "sec", "secs", "second", "seconds"],
    60: ["m", "min", "mins", "minute", "minutes"],
    3600: ["h", "hr", "hrs", "hour", "hours"],
    86400: ["d", "day", "days"],
    604800: ["w", "wk", "wks", "week", "weeks"],
}
UNIT_SECONDS = {name: mult for mult, names in _UNITS.items() for name in names}

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_COMPONENT = re.compile(r"\s*(" + _NUM + r")\s*([a-zA-Z]+)\s*")
_ISO = re.compile(
    r"P(?:(" + _NUM + r")W)?(?:(" + _NUM + r")D)?"
    r"(?:T(?:(" + _NUM + r")H)?(?:(" + _NUM + r")M)?(?:(" + _NUM + r")S)?)?"
)
_CLOCK = re.compile(r"(\d+):([0-5]?\d(?:\.\d+)?)(?::([0-5]?\d(?:\.\d+)?))?")


def _round(total: float) -> int:
    if total < 0:
        raise ValueError("negative duration")
    return int(total + 0.5)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # Bare integer seconds.
    if re.fullmatch(r"\d+", s):
        return int(s)

    # ISO 8601.
    m = _ISO.fullmatch(s.upper())
    if m and s.upper() not in ("P", "PT") and not s.upper().endswith("T"):
        if any(g is not None for g in m.groups()):
            mults = (604800, 86400, 3600, 60, 1)
            return _round(sum(float(g) * k for g, k in zip(m.groups(), mults) if g))

    # Clock notation.
    m = _CLOCK.fullmatch(s)
    if m:
        a, b, c = m.groups()
        if c is None:  # mm:ss
            return _round(int(a) * 60 + float(b))
        if "." in b:
            raise ValueError(f"invalid clock duration: {text!r}")
        return _round(int(a) * 3600 + int(b) * 60 + float(c))

    # Number+unit components.
    pos = 0
    total = 0.0
    found = False
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in UNIT_SECONDS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += float(m.group(1)) * UNIT_SECONDS[unit]
        found = True
        pos = m.end()
    if not found:
        raise ValueError(f"invalid duration: {text!r}")
    return _round(total)

